import manifest from "./image-manifest.json";

/** Pre-resized WebP variants of /public images, generated by `npm run images` (scripts/resize-images.mjs). */
type Variants = { name: string; widths: number[] };
const local = manifest as Record<string, Variants>;

const file = (v: Variants, w: number) => `/_img/${v.name}-${w}.webp`;

/** "/hero.jpeg", "/hero.jpeg?w=1" and a static import's "/_next/static/media/hero.0a1b2c3d.jpeg" → "/hero.jpeg". */
const key = (src: string) => src.split("?")[0].replace(/^\/_next\/static\/media\/(.+)\.[^./]+(\.\w+)$/, "/$1$2");

/** Smallest generated variant at least `width` wide (or the largest one); null if `src` has no variants. */
export function localVariant(src: string, width: number): string | null {
  const v = local[key(src)];
  if (!v) return null;
  return file(v, v.widths.find((w) => w >= width) ?? v.widths[v.widths.length - 1]);
}

/** `srcset` of every generated variant, for plain <img>/<source> tags that don't go through next/image. */
export function localSrcSet(src: string): string | undefined {
  const v = local[key(src)];
  return v?.widths.map((w) => `${file(v, w)} ${w}w`).join(", ");
}
